import java.util.*; 
 
class Codechef 
{ 
    public static void main(String[] args) 
    { 
        Scanner scn=new Scanner(System.in); 
        StringBuilder out=new StringBuilder(); 
        int test=scn.nextInt(); 
        for(int cas=0;cas<test;cas++){ 
            int cnt=scn.nextInt(); 
            int num=3*cnt; 
            int[] arr=new int[num]; 
            for(int idx=0;idx<num;idx++){ 
                arr[idx]=scn.nextInt(); 
            } 
            Arrays.sort(arr); 
            long[] pref=new long[num+1]; 
            for(int idx=1;idx<=num;idx++){ 
                pref[idx]=pref[idx-1]+arr[num-idx]; 
            } 
            long ans=0; 
            int two=cnt; 
            for(int one=0;one<=cnt;one++){ 
                two=Math.min(two,cnt-one); 
                while(two>0){ 
                    int mid=one+2*two; 
                    int end=num-2*one-two; 
                    long gain=3*(pref[end+1]-pref[end])-(pref[mid]-pref[mid-2]); 
                    if(gain<0){ 
                        break; 
                    } 
                    two--; 
                } 
                long curr=2*pref[one]+pref[one+2*two]+3*pref[num-2*one-two]; 
                ans=Math.max(ans,curr); 
            } 
            out.append(ans).append('\n'); 
        } 
        System.out.print(out); 
    } 
}
